select extensions.plan(16);
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000002","role":"authenticated"}';
set local role authenticated;
select extensions.lives_ok($$insert into public.prestamos(id,negocio_id) values('00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-000000000202')$$,'Se guarda un borrador incompleto');
select extensions.throws_like($$insert into public.prestamos(negocio_id) values('00000000-0000-4000-8000-000000000202')$$,'%prestamos_una_solicitud_abierta%','Una sola solicitud abierta por emprendedor');
select extensions.throws_like($$update public.prestamos set estado='en_revision' where id='00000000-0000-4000-8000-000000000102'$$,'%check constraint%','El borrador incompleto no se envía a revisión');
select extensions.throws_like($$update public.prestamos set estado='financiandose' where id='00000000-0000-4000-8000-000000000102'$$,'%borradores%','El emprendedor no publica su propia solicitud');
select extensions.throws_like($$update public.prestamos set monto=3001 where id='00000000-0000-4000-8000-000000000102'$$,'%fuera de límites%','Idea nueva respeta Bs3000');
select extensions.throws_like($$update public.prestamos set tasa_anual=7.01 where id='00000000-0000-4000-8000-000000000102'$$,'%fuera de límites%','Tasa superior al 7% rechazada');
select extensions.throws_like($$update public.prestamos set monto='NaN' where id='00000000-0000-4000-8000-000000000102'$$,'%monto_bob%','NaN no es un importe válido');
select extensions.lives_ok($$delete from public.prestamos where id='00000000-0000-4000-8000-000000000102'$$,'Se puede descartar un borrador');
reset role;
select extensions.is((select comision_originacion_pactada::numeric from public.prestamos where id='00000000-0000-4000-8000-000000000101'),2::numeric,'Originación pactada al publicar');
update public.parametros set valor=3 where clave='comision_originacion';
select extensions.is((select comision_originacion_pactada::numeric from public.prestamos where id='00000000-0000-4000-8000-000000000101'),2::numeric,'Cambiar parámetro no cambia préstamo publicado');
select extensions.throws_like($$update public.prestamos set comision_originacion_pactada=3 where id='00000000-0000-4000-8000-000000000101'$$,'%inmutables%','No se sobrescriben condiciones pactadas');
select extensions.throws_like($$delete from public.prestamos where id='00000000-0000-4000-8000-000000000101'$$,'%borradores%','Préstamo publicado no se elimina');
select extensions.throws_like($$update public.etapas set monto=301 where id='00000000-0000-4000-8000-000000000301'$$,'%Plan de etapas inválido%','La suma de las etapas debe conservar el total');
select extensions.is((select cantidad_cuotas from public.prestamos where id='00000000-0000-4000-8000-000000000101'),6,'Cantidad de cuotas calculada');
select extensions.is((select total_devolver::numeric from public.prestamos where id='00000000-0000-4000-8000-000000000101'),1035::numeric,'Bs1000 a seis meses con 7% anual devuelven Bs1035');
select extensions.is((select monto_cuota::numeric from public.prestamos where id='00000000-0000-4000-8000-000000000101'),172.50::numeric,'Cuota de ejemplo Bs172.50');
select * from extensions.finish();
